//! Unicode character properties as HarfBuzz 14.6.0 sees them, from Unicode 18.0.0.
//!
//! These are the properties shaping reads: [`GeneralCategory::of`],
//! [`combining_class`], [`Script::of`](crate::Script::of), [`mirroring`] and
//! [`decompose`]. The bidi properties, from Unicode 14.0.0, are in
//! [`bidi`](crate::bidi): [`BidiClass::of`](crate::bidi::BidiClass::of),
//! [`Bracket::of`](crate::bidi::Bracket::of), [`mirror`](crate::bidi::mirror) and
//! [`JoiningType::of`](crate::bidi::JoiningType::of).
//!
//! The tables are generated by `cargo xtask shape ucd`.

mod arabic;
pub(crate) mod bidi;
pub(crate) mod code_point;
mod syllabic;
#[rustfmt::skip] // Laid out by the generator.
mod syllabic_tables;
#[rustfmt::skip] // Laid out by the generator.
mod tables;
mod trie;

pub(crate) use arabic::{
    ArabicForm, ArabicJoining, ArabicLigature, ArabicLigatureSet, arabic_joining, arabic_ligatures,
    arabic_ligatures_3, arabic_mark_ligatures, arabic_presentation_forms,
};
pub(crate) use syllabic::{
    IndicCategory, IndicPosition, UseCategory, has_arabic_joining, indic_properties, is_use_script,
    use_category, vowel_constraints,
};

/// The General_Category of a character (UAX #44), as HarfBuzz assigns it.
// The discriminants are the generated tables' values.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum GeneralCategory {
    /// Cc
    Control,
    /// Cf
    Format,
    /// Cn
    Unassigned,
    /// Co
    PrivateUse,
    /// Cs
    Surrogate,
    /// Ll
    LowercaseLetter,
    /// Lm
    ModifierLetter,
    /// Lo
    OtherLetter,
    /// Lt
    TitlecaseLetter,
    /// Lu
    UppercaseLetter,
    /// Mc
    SpacingMark,
    /// Me
    EnclosingMark,
    /// Mn
    NonSpacingMark,
    /// Nd
    DecimalNumber,
    /// Nl
    LetterNumber,
    /// No
    OtherNumber,
    /// Pc
    ConnectPunctuation,
    /// Pd
    DashPunctuation,
    /// Pe
    ClosePunctuation,
    /// Pf
    FinalPunctuation,
    /// Pi
    InitialPunctuation,
    /// Po
    OtherPunctuation,
    /// Ps
    OpenPunctuation,
    /// Sc
    CurrencySymbol,
    /// Sk
    ModifierSymbol,
    /// Sm
    MathSymbol,
    /// So
    OtherSymbol,
    /// Zl
    LineSeparator,
    /// Zp
    ParagraphSeparator,
    /// Zs
    SpaceSeparator,
}

impl GeneralCategory {
    /// Every category, in discriminant order.
    const ALL: [Self; 30] = [
        Self::Control,
        Self::Format,
        Self::Unassigned,
        Self::PrivateUse,
        Self::Surrogate,
        Self::LowercaseLetter,
        Self::ModifierLetter,
        Self::OtherLetter,
        Self::TitlecaseLetter,
        Self::UppercaseLetter,
        Self::SpacingMark,
        Self::EnclosingMark,
        Self::NonSpacingMark,
        Self::DecimalNumber,
        Self::LetterNumber,
        Self::OtherNumber,
        Self::ConnectPunctuation,
        Self::DashPunctuation,
        Self::ClosePunctuation,
        Self::FinalPunctuation,
        Self::InitialPunctuation,
        Self::OtherPunctuation,
        Self::OpenPunctuation,
        Self::CurrencySymbol,
        Self::ModifierSymbol,
        Self::MathSymbol,
        Self::OtherSymbol,
        Self::LineSeparator,
        Self::ParagraphSeparator,
        Self::SpaceSeparator,
    ];

    /// The category whose discriminant is `index`; [`Unassigned`](Self::Unassigned)
    /// for an index beyond the last.
    pub(crate) const fn from_index(index: u8) -> Self {
        if (index as usize) < Self::ALL.len() {
            Self::ALL[index as usize]
        } else {
            Self::Unassigned
        }
    }

    /// The category of `c`, as `hb_unicode_general_category` gives it.
    #[must_use]
    pub fn of(c: char) -> Self {
        code_point::general_category(u32::from(c))
    }

    /// Mn, Mc or Me, as HarfBuzz's `HB_UNICODE_GENERAL_CATEGORY_IS_MARK`.
    #[must_use]
    pub const fn is_mark(self) -> bool {
        matches!(
            self,
            Self::SpacingMark | Self::EnclosingMark | Self::NonSpacingMark
        )
    }

    /// Lu, Ll, Lt, Lm or Lo, as HarfBuzz's `HB_UNICODE_GENERAL_CATEGORY_IS_LETTER`.
    #[must_use]
    pub const fn is_letter(self) -> bool {
        matches!(
            self,
            Self::LowercaseLetter
                | Self::ModifierLetter
                | Self::OtherLetter
                | Self::TitlecaseLetter
                | Self::UppercaseLetter
        )
    }
}

/// The Canonical_Combining_Class of `c`, as `hb_unicode_combining_class` gives
/// it: 0 for starters.
#[must_use]
pub fn combining_class(c: char) -> u8 {
    code_point::combining_class(u32::from(c))
}

/// The Bidi_Mirroring_Glyph of `c`, if it has one, as `hb_unicode_mirroring`
/// gives it.
#[must_use]
pub fn mirroring(c: char) -> Option<char> {
    let cp = u32::from(c);
    let mirrored = code_point::mirroring(cp);
    (mirrored != cp).then(|| char::from_u32(mirrored)).flatten()
}

/// A canonical decomposition, as `hb_unicode_decompose` gives it.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Decomposition {
    /// A singleton: the character is canonically equivalent to another one.
    Single(char),
    /// A pair: the character decomposes into these two, each of which may
    /// decompose further.
    Pair(char, char),
}

/// The canonical decomposition of `c` into one or two characters, if it has
/// one, as `hb_unicode_decompose` gives it. Hangul syllables decompose
/// algorithmically: LV into L and V, LVT into LV and T.
#[must_use]
pub fn decompose(c: char) -> Option<Decomposition> {
    let (a, b) = code_point::decompose(u32::from(c))?;
    let a = char::from_u32(a)?;
    Some(if b == 0 {
        Decomposition::Single(a)
    } else {
        Decomposition::Pair(a, char::from_u32(b)?)
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::Script;

    #[test]
    fn general_category_values() {
        for (i, category) in GeneralCategory::ALL.iter().enumerate() {
            assert_eq!(*category as usize, i);
            assert_eq!(GeneralCategory::from_index(i as u8), *category);
        }
        use GeneralCategory::*;
        assert_eq!(GeneralCategory::from_index(30), Unassigned);
        assert!(NonSpacingMark.is_mark() && SpacingMark.is_mark() && EnclosingMark.is_mark());
        assert!(!Format.is_mark() && OtherLetter.is_letter() && !OtherNumber.is_letter());
    }

    #[test]
    fn character_properties() {
        use GeneralCategory::*;
        assert_eq!(GeneralCategory::of('A'), UppercaseLetter);
        assert_eq!(GeneralCategory::of('\u{0627}'), OtherLetter);
        assert_eq!(GeneralCategory::of('\u{0301}'), NonSpacingMark);
        assert_eq!(GeneralCategory::of('\u{E000}'), PrivateUse);
        assert_eq!(GeneralCategory::of('\u{0378}'), Unassigned);

        assert_eq!(combining_class('\u{0301}'), 230);
        assert_eq!(combining_class('\u{05B0}'), 10);
        assert_eq!(combining_class('A'), 0);

        assert_eq!(Script::of('A').to_bytes(), *b"Latn");
        assert_eq!(Script::of('\u{0627}').to_bytes(), *b"Arab");
        assert_eq!(Script::of('\u{0301}'), Script::INHERITED);
        assert_eq!(Script::of(' '), Script::COMMON);
        assert_eq!(Script::of('\u{0378}'), Script::UNKNOWN);

        assert_eq!(mirroring('('), Some(')'));
        assert_eq!(mirroring('\u{2329}'), Some('\u{232A}'));
        assert_eq!(mirroring('A'), None);

        use Decomposition::*;
        assert_eq!(decompose('\u{00C0}'), Some(Pair('A', '\u{0300}')));
        assert_eq!(decompose('\u{212B}'), Some(Single('\u{00C5}')));
        assert_eq!(decompose('\u{AC00}'), Some(Pair('\u{1100}', '\u{1161}')));
        assert_eq!(decompose('\u{AC01}'), Some(Pair('\u{AC00}', '\u{11A8}')));
        assert_eq!(decompose('A'), None);
        assert_eq!(decompose('\u{FB01}'), None, "compatibility only");
    }
}
